-- L: whole-URL replacement.
UPDATE inform.politician_context pc
   SET sources = array_replace(pc.sources, m.old, m.neu)
  FROM tail_l m
 WHERE m.old = ANY(pc.sources);

-- A: row-scoped replacement, keyed on (politician_id, topic_id) as well as the URL.
UPDATE inform.politician_context pc
   SET sources = array_replace(pc.sources, m.old, m.neu)
  FROM tail_a m
 WHERE m.politician_id = pc.politician_id AND m.topic_id = pc.topic_id
   AND m.old = ANY(pc.sources);

DO $$
DECLARE v_n int; v_bad text;
BEGIN
  -- 1. Group L landed, counted per TARGET as distinct rows: two cited URLs share
  --    /House/Andy_Barr.htm, so a per-source count would double-count them.
  SELECT string_agg(format('%s: expected %s, found %s', t.neu, t.expected, x.n), E'\n') INTO v_bad
    FROM (VALUES
      ('https://www.ontheissues.org/CA/Pete_Aguilar_Energy_+_Oil.htm', 1),
      ('https://www.ontheissues.org/CA/Robert_Garcia.htm', 14),
      ('https://www.ontheissues.org/GA/Rick_Allen.htm', 6),
      ('https://www.ontheissues.org/House/Andy_Barr.htm', 13),
      ('https://www.ontheissues.org/House/Jahana_Hayes_Families_+_Children.htm', 1),
      ('https://www.ontheissues.org/House/Jahana_Hayes_Welfare_+_Poverty.htm', 2),
      ('https://www.ontheissues.org/House/Jill_Tokuda.htm', 1),
      ('https://www.ontheissues.org/House/Mark_Alford.htm', 2),
      ('https://www.ontheissues.org/IL/Chuy_Garcia.htm', 6),
      ('https://www.ontheissues.org/IN/Frank_Mrvan.htm', 7),
      ('https://www.ontheissues.org/MA/Jim_McGovern.htm', 31),
      ('https://www.ontheissues.org/MA/Katherine_Clark.htm', 24),
      ('https://www.ontheissues.org/MA/Lori_Trahan.htm', 5),
      ('https://www.ontheissues.org/MA/Steve_Lynch.htm', 4),
      ('https://www.ontheissues.org/Maura_Healey.htm', 18),
      ('https://www.ontheissues.org/Mike_Dunleavy.htm', 8),
      ('https://www.ontheissues.org/OH/Michael_Rulli.htm', 2),
      ('https://www.ontheissues.org/Senate/Ed_Markey.htm', 41),
      ('https://www.ontheissues.org/Senate/Mike_Rogers.htm', 1)
         ) AS t(neu, expected)
    JOIN LATERAL (
      SELECT count(*)::int AS n FROM inform.politician_context pc
        JOIN inform.politician_answers pa
          ON pa.politician_id = pc.politician_id AND pa.topic_id = pc.topic_id AND pa.value <> 0
       WHERE t.neu = ANY(pc.sources)) x ON true
   WHERE x.n <> t.expected;
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'group L per-target mismatch:%', E'\n' || v_bad; END IF;

  -- 2. No row still cites a group-L URL.
  SELECT count(*) INTO v_n FROM inform.politician_context pc
   WHERE EXISTS (SELECT 1 FROM unnest(pc.sources) s JOIN tail_l m ON m.old = s);
  IF v_n <> 0 THEN RAISE EXCEPTION '% row(s) still cite a group-L url', v_n; END IF;

  -- 3. Every group-A row moved, and only those rows.
  SELECT count(*) INTO v_n FROM tail_a m
    JOIN inform.politician_context pc
      ON pc.politician_id = m.politician_id AND pc.topic_id = m.topic_id
   WHERE m.neu = ANY(pc.sources);
  IF v_n <> 98 THEN RAISE EXCEPTION 'expected 98 group-A rows on the archive, found %', v_n; END IF;

  -- 4. 🔴 THE HELD ROWS ON GROUP-A URLS MUST BE UNTOUCHED. Same URL, different rows -- a URL-scoped
  --    UPDATE would have swept up exactly the rows the capture does NOT support.
  SELECT count(*) INTO v_n
    FROM inform.politician_context pc
    JOIN inform.politician_answers pa
      ON pa.politician_id = pc.politician_id AND pa.topic_id = pc.topic_id AND pa.value <> 0
   WHERE EXISTS (SELECT 1 FROM unnest(pc.sources) s JOIN tail_a m ON m.old = s)
     AND NOT EXISTS (SELECT 1 FROM tail_a m2
                      WHERE m2.politician_id = pc.politician_id AND m2.topic_id = pc.topic_id);
  IF v_n <> 15 THEN
    RAISE EXCEPTION 'held group-A rows changed: expected 15, found %', v_n;
  END IF;

  -- 5. No source vanished: every pre-image citation is either still present or was mapped.
  SELECT count(*) INTO v_n
    FROM inform.politician_context pc
